package com.brasa.restaurant.model;import jakarta.persistence.*;import java.math.BigDecimal;@Entity@Table(name="produtos")public class Produto extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;@Column(name="categoria_id",nullable=false)private String categoriaId;@Column(nullable=false)private String nome;@Column(length=2000)private String descricao;@Column(nullable=false,precision=12,scale=2)private BigDecimal preco;private String imagemUrl;private boolean disponivel=true;public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public String getCategoriaId(){return categoriaId;}public void setCategoriaId(String v){categoriaId=v;}public String getNome(){return nome;}public void setNome(String v){nome=v;}public String getDescricao(){return descricao;}public void setDescricao(String v){descricao=v;}public BigDecimal getPreco(){return preco;}public void setPreco(BigDecimal v){preco=v;}public String getImagemUrl(){return imagemUrl;}public void setImagemUrl(String v){imagemUrl=v;}public boolean isDisponivel(){return disponivel;}public void setDisponivel(boolean v){disponivel=v;}}
